import { useMemo, useState } from "react";
import { Icon, type IconName } from "@/components/icons";
import { Medal, type MedalType } from "@/components/Medal";
import { Button } from "@/components/ui/Button";
import { TextField } from "@/components/ui/TextField";
import { CardHeader, WorkspaceCard } from "@/components/workspace/WorkspaceCard";
import { DataTable, type DataColumn } from "@/components/workspace/DataTable";
import { DemoBanner } from "@/components/workspace/DemoBanner";
import { DocumentPreview } from "@/components/workspace/DocumentPreview";
import { Modal } from "@/components/workspace/Modal";
import { StatusBadge, ToneBadge } from "@/components/workspace/StatusBadge";
import { ROLE_CONFIGS } from "@/demo/roles";
import { ACTIVITIES, ALL_RECIPIENTS, CAMPAIGNS, CEREMONIES, DEMO_NOTICE, DOSSIERS, NOTIFICATIONS, STOCK } from "@/demo/data";
import type { DemoDossier, DemoPage, DemoRecipient, DemoRole } from "@/demo/types";
import { workspacePath } from "@/demo/navigation";
import { navigateTo } from "@/lib/router";
import { cn } from "@/utils/cn";
import { WorkspaceSidebar } from "@/components/workspace/WorkspaceSidebar";
import { WorkspaceTopbar } from "@/components/workspace/WorkspaceTopbar";

interface WorkspacePageProps { role: DemoRole; page: DemoPage; }

const MEDAL_TYPES: Record<string, MedalType> = { Bronze: "bronze", Argent: "argent", Or: "or" };

function Metric({ label, value, detail, icon, accent = "green", onClick }: { label: string; value: string; detail: string; icon: IconName; accent?: "green" | "gold" | "blue"; onClick?: () => void }) {
  const iconClass = accent === "green" ? "bg-republic-green-50 text-republic-green-600" : accent === "blue" ? "bg-republic-blue-50 text-republic-blue-600" : "bg-gold-100 text-gold-800";
  const content = <><span className={cn("flex size-10 shrink-0 items-center justify-center rounded-xl", iconClass)}><Icon name={icon} className="size-[19px]" /></span><span className="min-w-0"><span className="block text-[0.6875rem] font-medium text-muted">{label}</span><span className="mt-1 block text-2xl font-semibold tracking-[-0.04em] text-ink-900">{value}</span><span className="mt-1 block truncate text-[0.6875rem] text-muted">{detail}</span></span></>;
  return onClick ? <button type="button" onClick={onClick} className="flex w-full items-start gap-3 rounded-2xl border border-line bg-white p-4 text-left transition-all hover:-translate-y-0.5 hover:border-ink-100 hover:shadow-card">{content}</button> : <div className="flex items-start gap-3 rounded-2xl border border-line bg-white p-4">{content}</div>;
}

function PageIntro({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-[0.625rem] font-bold tracking-[0.18em] text-republic-green-700 uppercase">{eyebrow ?? "Espace connecté"}</p><h2 className="mt-2 text-[1.65rem] font-semibold tracking-[-0.035em] text-ink-900 sm:text-[2rem]">{title}</h2>{description ? <p className="mt-2 max-w-2xl text-[0.875rem] leading-relaxed text-muted">{description}</p> : null}</div>{action}</div>;
}

function QuickAction({ icon, label, onClick }: { icon: IconName; label: string; onClick: () => void }) { return <button type="button" onClick={onClick} className="flex items-center gap-2 rounded-xl border border-line bg-white px-3.5 py-2.5 text-[0.75rem] font-medium text-ink-700 transition hover:border-republic-green-200 hover:bg-republic-green-50 hover:text-republic-green-700"><Icon name={icon} className="size-4" />{label}</button>; }

function Overview({ role, go }: { role: DemoRole; go: (page: DemoPage) => void }) {
  const isRecipient = role === "recipient";
  const isRegisseur = role === "regisseur";
  const isInternal = ["secretariat", "ministre", "dgt", "dr", "service"].includes(role);
  return <>
    <PageIntro eyebrow={ROLE_CONFIGS[role].shortLabel} title={isRecipient ? "Bonjour, votre espace de mérite" : `Vue d'ensemble`} description={isRecipient ? "Retrouvez vos distinctions, vos cérémonies et les documents associés." : ROLE_CONFIGS[role].description + ". Toutes les données affichées sont fictives et destinées à la démonstration."} action={<div className="flex flex-wrap gap-2"><QuickAction icon="bell" label="Notifications" onClick={() => go("notifications")} />{role === "demandeur" ? <QuickAction icon="plus" label="Nouveau dossier" onClick={() => go("new-dossier")} /> : null}</div>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      {isRecipient ? <><Metric label="Distinctions obtenues" value="4" detail="Depuis 2011" icon="medal" accent="gold" onClick={() => go("recipients")} /><Metric label="Prochaine cérémonie" value="04 avr." detail="Libreville" icon="calendar" accent="blue" onClick={() => go("ceremonies")} /><Metric label="Documents à fournir" value="2" detail="À compléter" icon="fileText" accent="green" onClick={() => go("documents")} /><Metric label="Notifications" value="3" detail="Non lues" icon="bell" accent="blue" onClick={() => go("notifications")} /></> : isRegisseur ? <><Metric label="Médailles disponibles" value="287" detail="Tous types confondus" icon="medal" accent="gold" onClick={() => go("stock")} /><Metric label="Diplômes en stock" value="360" detail="86 réservés" icon="fileText" accent="blue" /><Metric label="Approvisionnements" value="3" detail="En cours" icon="truck" accent="green" onClick={() => go("supplies")} /><Metric label="Retraits en attente" value="18" detail="À préparer" icon="users" accent="gold" onClick={() => go("withdrawals")} /></> : isInternal ? <><Metric label="Dossiers reçus" value="42" detail="+8 ce mois" icon="folder" accent="blue" onClick={() => go("dossiers")} /><Metric label="En attente de décision" value="17" detail="À examiner" icon="checkCircle" accent="gold" onClick={() => go("decisions")} /><Metric label="Recours à examiner" value="4" detail="3 nouveaux" icon="scale" accent="green" onClick={() => go("recours")} /><Metric label="Cérémonies" value="6" detail="À confirmer" icon="calendar" accent="blue" onClick={() => go("ceremonies")} /></> : <><Metric label="Dossiers soumis" value="12" detail="+2 ce trimestre" icon="folder" accent="green" onClick={() => go("dossiers")} /><Metric label="Dossiers en cours" value="5" detail="Instruction" icon="clock" accent="blue" onClick={() => go("dossiers")} /><Metric label="Compléments demandés" value="3" detail="À traiter" icon="upload" accent="gold" onClick={() => go("complements")} /><Metric label="Dossiers approuvés" value="4" detail="2 cérémonies planifiées" icon="checkCircle" accent="green" onClick={() => go("dossiers")} /></>}
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.25fr_0.75fr]">
      <WorkspaceCard><CardHeader title={isRegisseur ? "État indicatif du stock" : isRecipient ? "Dernières distinctions" : "Activité récente"} action={<Button variant="ghost" size="sm" onClick={() => go(isRecipient ? "recipients" : isRegisseur ? "stock" : "activity")}>Voir tout <Icon name="arrowRight" className="size-3.5" /></Button>} />{isRecipient ? <div className="grid gap-3 p-5 sm:grid-cols-2">{["Médaille d'argent", "Médaille de bronze", "Médaille d'or", "Médaille de bronze"].map((label, index) => <div key={`${label}-${index}`} className="flex items-center gap-3 rounded-xl border border-line bg-canvas p-3"><span className="w-12"><Medal type={index === 2 ? "or" : index === 0 ? "argent" : "bronze"} size="sm" showRibbon={false} /></span><span><span className="block text-[0.75rem] font-semibold text-ink-900">{label}</span><span className="mt-1 block text-[0.6875rem] text-muted">Campagne {2021 + index}</span></span></div>)}</div> : isRegisseur ? <div className="space-y-4 p-5">{STOCK.map((item) => <div key={item.type}><div className="flex items-center justify-between text-[0.75rem]"><span className="font-medium text-ink-800">{item.type}</span><span className="text-muted">{item.quantity} disponibles</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-canvas"><span className={cn("block h-full rounded-full", item.quantity < item.threshold ? "bg-gold-400" : "bg-republic-green-500")} style={{ width: `${Math.min((item.quantity / (item.quantity + item.reserved)) * 100, 100)}%` }} /></div><p className="mt-1 text-[0.625rem] text-muted">{item.reserved} réservés · seuil illustratif {item.threshold}</p></div>)}</div> : <div className="divide-y divide-line">{ACTIVITIES.slice(0, 4).map((activity) => <div key={`${activity.reference}-${activity.date}`} className="flex items-start gap-3 px-5 py-4 sm:px-6"><span className="mt-1 flex size-8 shrink-0 items-center justify-center rounded-full bg-republic-green-50 text-republic-green-700"><Icon name="check" className="size-4" /></span><p className="min-w-0 flex-1 text-[0.8125rem] leading-relaxed text-ink-800"><strong>{activity.actor}</strong> {activity.action} <span className="text-muted">{activity.reference}</span><span className="mt-1 block text-[0.6875rem] text-muted">{activity.date}</span></p></div>)}</div>}</WorkspaceCard>
      <WorkspaceCard><CardHeader title={isRecipient ? "Prochaine cérémonie" : "Répartition indicative"} />{isRecipient ? <div className="p-5"><div className="rounded-xl bg-ink-900 p-5 text-white"><p className="text-[0.625rem] font-bold tracking-[0.14em] text-gold-300 uppercase">04 avril 2026</p><p className="mt-2 text-lg font-semibold">Cérémonie de remise</p><p className="mt-2 flex items-center gap-2 text-[0.75rem] text-ink-200"><Icon name="mapPin" className="size-4" />Hôtel de ville, Libreville</p></div><Button variant="secondary" size="sm" fullWidth className="mt-4" onClick={() => go("ceremonies")}>Voir les informations</Button></div> : <div className="p-5"><div className="flex items-center gap-5"><div className="relative flex size-32 shrink-0 items-center justify-center rounded-full" style={{ background: "conic-gradient(#009E60 0 48%, #3A75C4 48% 77%, #FCD116 77% 91%, #E5EAF0 91% 100%)" }}><div className="flex size-20 items-center justify-center rounded-full bg-white text-center"><span><strong className="block text-xl text-ink-900">42</strong><small className="text-[0.6rem] text-muted">total</small></span></div></div><div className="space-y-2.5 text-[0.75rem] text-muted"><span className="flex items-center gap-2"><i className="size-2 rounded-full bg-republic-green-500" />En cours <strong className="text-ink-900">20</strong></span><span className="flex items-center gap-2"><i className="size-2 rounded-full bg-republic-blue-500" />Approuvés <strong className="text-ink-900">12</strong></span><span className="flex items-center gap-2"><i className="size-2 rounded-full bg-gold-400" />À compléter <strong className="text-ink-900">6</strong></span></div></div><p className="mt-5 rounded-lg bg-canvas p-3 text-[0.6875rem] leading-relaxed text-muted">Répartition de démonstration, non représentative de données officielles.</p></div>}</WorkspaceCard>
    </div>
  </>;
}

function DossiersPage({ role, go }: { role: DemoRole; go: (page: DemoPage) => void }) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("Tous les statuts");
  const [selected, setSelected] = useState<DemoDossier | null>(null);
  const rows = DOSSIERS.filter((dossier) => (status === "Tous les statuts" || dossier.status.label === status) && `${dossier.reference} ${dossier.applicant} ${dossier.campaign}`.toLowerCase().includes(query.toLowerCase()));
  const columns: DataColumn<DemoDossier>[] = [
    { key: "reference", label: "Référence", render: (row) => <button type="button" onClick={() => setSelected(row)} className="font-semibold text-republic-blue-700 hover:underline">{row.reference}</button> },
    { key: "applicant", label: "Demandeur / campagne", render: (row) => <div><p className="max-w-52 truncate font-medium text-ink-900">{row.applicant}</p><p className="mt-1 max-w-52 truncate text-[0.6875rem] text-muted">{row.campaign.split(" — ")[0]}</p></div> },
    { key: "date", label: "Soumission", render: (row) => row.submitted },
    { key: "count", label: "Récipiendaires", render: (row) => <span className="font-medium text-ink-900">{row.recipientCount}</span> },
    { key: "recipient", label: "Destinataire initial", render: (row) => <span className="max-w-40 truncate block">{row.initialRecipient}</span> },
    { key: "status", label: "Statut", render: (row) => <StatusBadge status={row.status} /> },
    { key: "action", label: "", render: (row) => <button type="button" onClick={() => setSelected(row)} className="rounded-lg p-2 text-muted hover:bg-canvas hover:text-ink-900"><Icon name="more" className="size-4" /></button> },
  ];
  return <><PageIntro eyebrow={role === "demandeur" ? "Mon activité" : "Instruction"} title={role === "demandeur" ? "Mes dossiers" : "Dossiers transmis"} description="Une vue cohérente des dossiers de démonstration, de leur réception à la remise des distinctions." action={role === "demandeur" ? <Button onClick={() => go("new-dossier")}><Icon name="plus" className="size-4" />Nouveau dossier</Button> : undefined} /><div className="mb-4 flex flex-col gap-3 rounded-2xl border border-line bg-white p-3 sm:flex-row"><label className="relative min-w-0 flex-1"><span className="sr-only">Rechercher un dossier</span><Icon name="search" className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} className="h-10 w-full rounded-xl border border-line bg-canvas pl-9 pr-3 text-[0.8125rem] outline-none focus:border-republic-green-500 focus:ring-4 focus:ring-republic-green-100" placeholder="Rechercher une référence, un demandeur…" /></label><label className="relative"><span className="sr-only">Filtrer par statut</span><Icon name="filter" className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted" /><select value={status} onChange={(event) => setStatus(event.target.value)} className="h-10 w-full min-w-48 appearance-none rounded-xl border border-line bg-canvas pl-9 pr-8 text-[0.8125rem] text-ink-700 outline-none focus:border-republic-green-500"><option>Tous les statuts</option>{Array.from(new Set(DOSSIERS.map((item) => item.status.label))).map((item) => <option key={item}>{item}</option>)}</select></label><Button variant="secondary" size="sm" onClick={() => { setQuery(""); setStatus("Tous les statuts"); }}><Icon name="refresh" className="size-4" />Réinitialiser</Button></div><DataTable columns={columns} rows={rows} rowKey={(row) => row.reference} /><Modal open={Boolean(selected)} onClose={() => setSelected(null)} title={selected?.reference ?? "Dossier"} description={selected?.campaign}><DossierDetail dossier={selected} onClose={() => setSelected(null)} go={go} /></Modal></>;
}

function DossierDetail({ dossier, onClose, go }: { dossier: DemoDossier | null; onClose: () => void; go: (page: DemoPage) => void }) {
  if (!dossier) return null;
  return <div><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-canvas p-4"><p className="text-[0.6875rem] text-muted">Demandeur</p><p className="mt-1 text-sm font-medium text-ink-900">{dossier.applicant}</p></div><div className="rounded-xl bg-canvas p-4"><p className="text-[0.6875rem] text-muted">Destinataire initial</p><p className="mt-1 text-sm font-medium text-ink-900">{dossier.initialRecipient}</p></div></div><div className="mt-5 flex items-center justify-between"><span className="text-sm font-semibold text-ink-900">Statut actuel</span><StatusBadge status={dossier.status} /></div><div className="mt-5 rounded-xl border border-line p-4"><p className="text-[0.6875rem] font-bold tracking-[0.12em] text-muted uppercase">Chronologie visible</p><ol className="mt-4 space-y-4">{["Dossier soumis", "Transmission hiérarchique", dossier.status.label].map((item, index) => <li key={item} className="flex gap-3"><span className={cn("flex size-6 shrink-0 items-center justify-center rounded-full text-[0.625rem] font-bold", index === 2 ? "bg-gold-100 text-gold-800" : "bg-republic-green-50 text-republic-green-700")}>{index + 1}</span><span className="text-[0.8125rem] text-ink-800">{item}<small className="mt-0.5 block text-muted">Étape de démonstration</small></span></li>)}</ol></div><div className="mt-5"><p className="text-sm font-semibold text-ink-900">Récipiendaires ({dossier.recipients.length})</p><div className="mt-3 divide-y divide-line rounded-xl border border-line">{dossier.recipients.map((recipient) => <div key={recipient.id} className="flex items-center justify-between gap-3 px-3 py-3"><span><span className="block text-[0.8125rem] font-medium text-ink-900">{recipient.name}</span><span className="block text-[0.6875rem] text-muted">{recipient.role}</span></span><span className="flex items-center gap-2"><span className="text-[0.6875rem] text-muted">{recipient.medal}</span><ToneBadge label={recipient.instruction} tone={recipient.instruction === "Validé" ? "success" : recipient.instruction === "À compléter" ? "warning" : "info"} /></span></div>)}</div></div><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" size="sm" onClick={onClose}>Fermer</Button><Button size="sm" onClick={() => { onClose(); go("documents"); }}>Voir les pièces</Button></div></div>;
}

function RecipientsPage({ role }: { role: DemoRole }) {
  const [query, setQuery] = useState("");
  const rows = ALL_RECIPIENTS.filter((recipient) => `${recipient.name} ${recipient.company} ${recipient.medal}`.toLowerCase().includes(query.toLowerCase()));
  const columns: DataColumn<DemoRecipient>[] = [
    { key: "name", label: "Récipiendaire", render: (row) => <div className="flex items-center gap-3"><span className="flex size-8 items-center justify-center rounded-full bg-ink-100 text-[0.625rem] font-bold text-ink-700">{row.name.split(" ").map((part) => part[0]).join("").slice(0, 2)}</span><span><span className="block font-medium text-ink-900">{row.name}</span><span className="block text-[0.6875rem] text-muted">{row.id}</span></span></div> },
    { key: "company", label: "Employeur", render: (row) => row.company },
    { key: "role", label: "Fonction", render: (row) => row.role },
    { key: "seniority", label: "Ancienneté", render: (row) => `${row.seniority} ans` },
    { key: "medal", label: "Médaille", render: (row) => <span className="inline-flex items-center gap-2"><span className="w-6"><Medal type={MEDAL_TYPES[row.medal]} size="sm" showRibbon={false} /></span>{row.medal}</span> },
    { key: "instruction", label: "État", render: (row) => <ToneBadge label={row.instruction} tone={row.instruction === "Validé" ? "success" : row.instruction === "À compléter" ? "warning" : row.instruction === "Refusé" ? "danger" : "info"} /> },
  ];
  return <><PageIntro eyebrow={role === "recipient" ? "Mon espace" : "Instruction"} title={role === "recipient" ? "Mes distinctions" : "Récipiendaires"} description="Identités et distinctions de démonstration, partagées de manière cohérente entre les espaces." /><div className="mb-4 flex items-center gap-3 rounded-2xl border border-line bg-white p-3"><div className="relative flex-1"><Icon name="search" className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Rechercher une personne…" className="h-10 w-full rounded-xl border border-line bg-canvas pl-9 pr-3 text-[0.8125rem] outline-none focus:border-republic-green-500" /></div><span className="hidden text-[0.75rem] text-muted sm:block">{rows.length} résultat{rows.length > 1 ? "s" : ""}</span></div><DataTable columns={columns} rows={rows} rowKey={(row) => row.id} /></>;
}

function NewDossierPage({ setToast }: { setToast: (message: string) => void }) {
  const [step, setStep] = useState(1);
  const [recipients, setRecipients] = useState([{ id: "new-1", name: "Aline Moubamba", function: "Directrice administrative", seniority: "18", medal: "Bronze" }]);
  const [submitted, setSubmitted] = useState(false);
  const addRecipient = () => setRecipients((current) => [...current, { id: `new-${current.length + 1}`, name: "Nouveau récipiendaire", function: "Fonction à renseigner", seniority: "10", medal: "Bronze" }]);
  if (submitted) return <div className="mx-auto max-w-xl py-12 text-center"><span className="mx-auto flex size-16 items-center justify-center rounded-full bg-republic-green-50 text-republic-green-600"><Icon name="checkCircle" className="size-8" /></span><h2 className="mt-6 text-2xl font-semibold text-ink-900">Soumission simulée</h2><p className="mt-3 text-sm leading-relaxed text-muted">La maquette a enregistré votre action. Aucun dossier n&apos;a été transmis à un serveur.</p><Button className="mt-7" onClick={() => setSubmitted(false)}>Créer un autre brouillon</Button></div>;
  const steps = ["Informations générales", "Courrier d'initiation", "Récipiendaires", "Documents", "Récapitulatif"];
  return <><PageIntro eyebrow="Dépôt de démonstration" title="Nouveau dossier" description="Assistant visuel en cinq étapes. Toutes les modifications restent en mémoire dans cette démonstration." /><div className="mb-6 overflow-x-auto"><ol className="flex min-w-[650px] items-start">{steps.map((label, index) => <li key={label} className="relative flex flex-1 flex-col items-center text-center"><span className={cn("relative z-10 flex size-9 items-center justify-center rounded-full border text-xs font-bold", index + 1 <= step ? "border-republic-green-500 bg-republic-green-500 text-white" : "border-line-strong bg-white text-muted")}>{index + 1 <= step ? <Icon name="check" className="size-4" /> : index + 1}</span>{index < steps.length - 1 ? <span className={cn("absolute top-4 left-1/2 h-px w-full", index + 1 < step ? "bg-republic-green-500" : "bg-line-strong")} /> : null}<span className={cn("mt-2 max-w-28 text-[0.625rem] font-medium", index + 1 === step ? "text-ink-900" : "text-muted")}>{label}</span></li>)}</ol></div><WorkspaceCard className="p-5 sm:p-7">{step === 1 ? <div className="grid gap-5 sm:grid-cols-2"><TextField id="applicant" label="Entreprise ou ministère demandeur" defaultValue="Société Gabonaise de Services et d'Industrie" /><TextField id="reference" label="Référence interne" placeholder="REF-ENT-2026-01" /><label className="sm:col-span-2"><span className="mb-1.5 block text-sm font-medium text-ink-800">Campagne de distinction</span><select className="h-12 w-full rounded-xl border border-line-strong bg-white px-4 text-sm text-ink-800 outline-none focus:border-republic-green-500"><option>{CAMPAIGNS[0]}</option><option>{CAMPAIGNS[1]}</option></select></label><label className="sm:col-span-2"><span className="mb-1.5 block text-sm font-medium text-ink-800">Destinataire initial</span><select className="h-12 w-full rounded-xl border border-line-strong bg-white px-4 text-sm text-ink-800 outline-none focus:border-republic-green-500"><option>Ministre</option><option>Direction Générale du Travail</option><option>Direction Régionale du Travail</option></select></label></div> : step === 2 ? <div><div className="rounded-2xl border border-dashed border-republic-green-300 bg-republic-green-50/50 p-8 text-center"><Icon name="upload" className="mx-auto size-8 text-republic-green-600" /><p className="mt-3 text-sm font-semibold text-ink-900">Déposer le courrier d&apos;initiation</p><p className="mt-1 text-xs text-muted">PDF ou DOCX · 10 Mo maximum · fichier local uniquement</p><Button variant="secondary" size="sm" className="mt-5" onClick={() => setToast("Sélection de fichier simulée : courrier-initiation-2026.pdf")}>Choisir un fichier</Button></div><div className="mt-4 flex items-center gap-3 rounded-xl border border-line p-3"><Icon name="fileText" className="size-5 text-republic-blue-600" /><span className="flex-1 text-xs font-medium text-ink-800">courrier-initiation-2026.pdf <small className="ml-2 text-muted">1,2 Mo</small></span><Icon name="checkCircle" className="size-4 text-republic-green-600" /></div></div> : step === 3 ? <div><div className="flex items-center justify-between gap-3"><div><h3 className="text-sm font-semibold text-ink-900">Liste des récipiendaires</h3><p className="mt-1 text-xs text-muted">Ajoutez les personnes concernées par cette demande.</p></div><Button size="sm" onClick={addRecipient}><Icon name="plus" className="size-4" />Ajouter</Button></div><div className="mt-5 overflow-x-auto rounded-xl border border-line"><table className="min-w-[650px] w-full text-left text-xs"><thead className="bg-canvas"><tr><th className="px-4 py-3 font-bold text-muted uppercase">Nom et prénom</th><th className="px-4 py-3 font-bold text-muted uppercase">Fonction</th><th className="px-4 py-3 font-bold text-muted uppercase">Ancienneté</th><th className="px-4 py-3 font-bold text-muted uppercase">Médaille</th><th /></tr></thead><tbody className="divide-y divide-line">{recipients.map((recipient, index) => <tr key={recipient.id}><td className="px-4 py-3 font-medium text-ink-900">{recipient.name}</td><td className="px-4 py-3 text-muted">{recipient.function}</td><td className="px-4 py-3 text-muted">{recipient.seniority} ans</td><td className="px-4 py-3"><span className="inline-flex items-center gap-2"><span className="w-7"><Medal type={MEDAL_TYPES[recipient.medal]} size="sm" showRibbon={false} /></span>{recipient.medal}</span></td><td className="px-4 py-3 text-right"><button type="button" onClick={() => setRecipients((current) => current.filter((_, rowIndex) => rowIndex !== index))} className="rounded p-1.5 text-muted hover:bg-red-50 hover:text-red-600"><Icon name="x" className="size-4" /></button></td></tr>)}</tbody></table></div></div> : step === 4 ? <div className="space-y-4"><label className="flex cursor-pointer items-center gap-4 rounded-xl border border-dashed border-line-strong p-5 hover:border-republic-green-300"><span className="flex size-11 items-center justify-center rounded-xl bg-republic-green-50 text-republic-green-600"><Icon name="upload" className="size-5" /></span><span><span className="block text-sm font-medium text-ink-900">Ajouter le DTS</span><span className="mt-1 block text-xs text-muted">Document de travail et de synthèse</span></span><input type="file" className="sr-only" /></label><label className="flex cursor-pointer items-center gap-4 rounded-xl border border-dashed border-line-strong p-5 hover:border-republic-green-300"><span className="flex size-11 items-center justify-center rounded-xl bg-republic-blue-50 text-republic-blue-600"><Icon name="plus" className="size-5" /></span><span><span className="block text-sm font-medium text-ink-900">Autres justificatifs</span><span className="mt-1 block text-xs text-muted">Attestations, états de service, pièces utiles</span></span><input type="file" className="sr-only" /></label></div> : <div className="space-y-4"><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-canvas p-4"><p className="text-xs text-muted">Destinataire</p><p className="mt-1 text-sm font-semibold text-ink-900">Direction Générale du Travail</p></div><div className="rounded-xl bg-canvas p-4"><p className="text-xs text-muted">Récipiendaires</p><p className="mt-1 text-sm font-semibold text-ink-900">{recipients.length}</p></div><div className="rounded-xl bg-canvas p-4"><p className="text-xs text-muted">Pièces</p><p className="mt-1 text-sm font-semibold text-ink-900">3 fichiers</p></div></div><p className="rounded-xl border border-gold-200 bg-gold-50 p-4 text-xs leading-relaxed text-gold-800">Vérifiez les informations avant la soumission. Cette action sera uniquement simulée.</p></div>}<div className="mt-8 flex flex-col-reverse justify-between gap-3 border-t border-line pt-5 sm:flex-row"><Button variant="secondary" onClick={() => setStep((current) => Math.max(1, current - 1))} disabled={step === 1}>Retour</Button><div className="flex gap-2"><Button variant="ghost" onClick={() => setToast("Brouillon enregistré localement pour la démonstration.")}>Enregistrer le brouillon</Button>{step < 5 ? <Button onClick={() => setStep((current) => current + 1)}>Continuer <Icon name="arrowRight" className="size-4" /></Button> : <Button onClick={() => setSubmitted(true)}>Soumettre la demande <Icon name="check" className="size-4" /></Button>}</div></div></WorkspaceCard></>;
}

function NotificationsPage() {
  const [items, setItems] = useState(NOTIFICATIONS);
  return <><PageIntro eyebrow="Centre de notifications" title="Notifications" description="Alertes locales et fictives associées à votre profil de démonstration." action={<Button variant="secondary" size="sm" onClick={() => setItems((current) => current.map((item) => ({ ...item, read: true })))}><Icon name="check" className="size-4" />Tout marquer lu</Button>} /><div className="space-y-3">{items.map((item) => <div key={item.id} className={cn("flex items-start gap-4 rounded-2xl border bg-white p-5 transition", item.read ? "border-line" : "border-republic-green-200 bg-republic-green-50/20")}><span className={cn("mt-0.5 flex size-10 shrink-0 items-center justify-center rounded-xl", item.tone === "warning" ? "bg-gold-100 text-gold-800" : item.tone === "success" ? "bg-republic-green-50 text-republic-green-700" : "bg-republic-blue-50 text-republic-blue-700")}><Icon name={item.tone === "success" ? "checkCircle" : item.tone === "warning" ? "alert" : "bell"} className="size-5" /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><p className="text-sm font-semibold text-ink-900">{item.title}</p><time className="text-[0.6875rem] text-muted">{item.date}</time></div><p className="mt-1 text-[0.8125rem] leading-relaxed text-muted">{item.description}</p>{item.reference ? <span className="mt-2 inline-block rounded-md bg-canvas px-2 py-1 text-[0.625rem] font-medium text-ink-700">{item.reference}</span> : null}</div>{!item.read ? <button type="button" onClick={() => setItems((current) => current.map((notification) => notification.id === item.id ? { ...notification, read: true } : notification))} className="text-[0.6875rem] font-semibold text-republic-green-700 hover:underline">Marquer lu</button> : null}</div>)}</div></>;
}

function ActivityPage() { return <><PageIntro eyebrow="Traçabilité" title="Journal d'activité" description="Chronologie illustrative des actions et transmissions. L'espace demandeur n'expose pas les détails internes." /><WorkspaceCard><CardHeader title="Activité récente" /><div className="divide-y divide-line">{ACTIVITIES.map((activity) => <div key={`${activity.reference}-${activity.date}`} className="flex gap-4 px-5 py-5 sm:px-6"><span className="relative flex size-9 shrink-0 items-center justify-center rounded-full bg-ink-50 text-ink-700"><Icon name="clock" className="size-4" /></span><div className="min-w-0 flex-1"><p className="text-sm text-ink-800"><strong>{activity.actor}</strong> <span className="text-muted">({activity.role})</span> {activity.action} <strong>{activity.reference}</strong></p><p className="mt-1 text-xs text-muted">{activity.date} · {activity.comment}</p></div></div>)}</div></WorkspaceCard></>; }

function DocumentsPage() { return <><PageIntro eyebrow="Pièces et justificatifs" title="Documents à fournir" description="Les pièces affichées sont des exemples de fichiers attendus dans la démonstration." /><div className="grid gap-5 md:grid-cols-[1fr_0.7fr]"><WorkspaceCard><CardHeader title="Liste des pièces" /><div className="divide-y divide-line">{["DTS — Document de travail et de synthèse", "Attestation de travail", "Pièce d'identité", "Photo de la cérémonie"].map((item, index) => <div key={item} className="flex items-center gap-3 px-5 py-4"><span className={cn("flex size-9 items-center justify-center rounded-lg", index < 2 ? "bg-gold-100 text-gold-800" : "bg-canvas text-muted")}><Icon name="fileText" className="size-4" /></span><div className="flex-1"><p className="text-[0.8125rem] font-medium text-ink-900">{item}</p><p className="mt-1 text-[0.6875rem] text-muted">{index < 2 ? "À fournir" : "Optionnel dans la démo"}</p></div><ToneBadge label={index < 2 ? "À compléter" : "Reçu"} tone={index < 2 ? "warning" : "success"} /></div>)}</div></WorkspaceCard><WorkspaceCard className="p-6"><div className="rounded-2xl border border-dashed border-republic-green-300 bg-republic-green-50/50 p-7 text-center"><Icon name="upload" className="mx-auto size-8 text-republic-green-600" /><p className="mt-3 text-sm font-semibold text-ink-900">Ajouter un document</p><p className="mt-1 text-xs leading-relaxed text-muted">Glissez un fichier ici ou sélectionnez-le. Aucun envoi réel.</p><Button size="sm" variant="secondary" className="mt-5">Choisir un fichier</Button></div></WorkspaceCard></div></>; }

function CeremoniesPage() { const [selected, setSelected] = useState<(typeof CEREMONIES)[number] | null>(null); return <><PageIntro eyebrow="Calendrier des distinctions" title="Cérémonies" description="Vue des cérémonies fictives, dates, lieux et informations logistiques." action={<Button variant="secondary" size="sm" onClick={() => setSelected(CEREMONIES[0])}><Icon name="calendar" className="size-4" />Vue calendrier</Button>} /><div className="grid gap-4 md:grid-cols-3">{CEREMONIES.map((ceremony) => <WorkspaceCard key={ceremony.id} className="p-5"><div className="flex items-center justify-between gap-3"><span className="rounded-lg bg-republic-blue-50 px-2.5 py-1 text-[0.6875rem] font-semibold text-republic-blue-700">{ceremony.date}</span><ToneBadge label={ceremony.status} tone={ceremony.tone} /></div><h3 className="mt-5 text-sm font-semibold leading-snug text-ink-900">{ceremony.title}</h3><p className="mt-3 flex items-center gap-2 text-xs text-muted"><Icon name="mapPin" className="size-4" />{ceremony.location}</p><p className="mt-2 flex items-center gap-2 text-xs text-muted"><Icon name="users" className="size-4" />{ceremony.participants} participants</p><Button variant="ghost" size="sm" className="mt-5 px-0" onClick={() => setSelected(ceremony)}>Voir le détail <Icon name="arrowRight" className="size-3.5" /></Button></WorkspaceCard>)}</div><Modal open={Boolean(selected)} onClose={() => setSelected(null)} title={selected?.title ?? "Cérémonie"} description="Fiche logistique de démonstration"><div className="space-y-3 text-sm"><p className="flex items-center gap-2 text-ink-800"><Icon name="calendar" className="size-4 text-republic-blue-600" />{selected?.date}</p><p className="flex items-center gap-2 text-ink-800"><Icon name="mapPin" className="size-4 text-republic-blue-600" />{selected?.location}</p><p className="flex items-center gap-2 text-ink-800"><Icon name="users" className="size-4 text-republic-blue-600" />{selected?.participants} participants prévus</p></div><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" size="sm" onClick={() => setSelected(null)}>Fermer</Button><Button size="sm" onClick={() => setSelected(null)}>Confirmer la lecture</Button></div></Modal></>; }

function PaymentsPage() { return <><PageIntro eyebrow="Trésor et quittances" title="Ordres de recette" description="Montants, quittances et paiements présentés comme des exemples. Aucune transaction financière n'est possible." /><div className="grid gap-5 lg:grid-cols-[1fr_0.7fr]"><WorkspaceCard><CardHeader title="Ordres disponibles" action={<ToneBadge label="2 exemples" tone="info" />} /><div className="divide-y divide-line">{[{ ref: "OR-2025-00841", dossier: "DNG-2025-00841", amount: "1 260 000 FCFA", status: "En attente de paiement", tone: "warning" as const }, { ref: "OR-2026-00112", dossier: "DNG-2025-01106", amount: "2 840 000 FCFA", status: "Quittance enregistrée", tone: "success" as const }].map((order) => <div key={order.ref} className="flex flex-wrap items-center gap-4 px-5 py-5"><span className="flex size-10 items-center justify-center rounded-xl bg-republic-blue-50 text-republic-blue-700"><Icon name="fileText" className="size-5" /></span><div className="min-w-32 flex-1"><p className="text-sm font-semibold text-ink-900">{order.ref}</p><p className="mt-1 text-[0.6875rem] text-muted">Dossier {order.dossier} · montant fictif</p></div><span className="text-sm font-semibold text-ink-900">{order.amount}</span><ToneBadge label={order.status} tone={order.tone} /><Button variant="ghost" size="sm"><Icon name="download" className="size-4" />Aperçu</Button></div>)}</div></WorkspaceCard><DocumentPreview type="Ordre de recette" reference="OR-2025-00841" compact /></div></>; }

function NewDecisionPage({ role }: { role: DemoRole }) { const [modal, setModal] = useState<"approve" | "reject" | null>(null); const [done, setDone] = useState(""); return <><PageIntro eyebrow={ROLE_CONFIGS[role].shortLabel} title="Décisions initiales" description={`${role === "dr" ? "Le DR est présenté comme l'autorité de décision finale sur le dossier initial." : "Interface de démonstration pour consulter et enregistrer un avis."} Aucune décision réelle n'est prise.`} /><WorkspaceCard><CardHeader title="Dossier en attente de décision" action={<ToneBadge label="À examiner" tone="warning" />} /><div className="grid gap-4 p-5 sm:grid-cols-3"><div><p className="text-[0.6875rem] text-muted">Référence</p><p className="mt-1 text-sm font-semibold text-ink-900">DNG-2026-00418</p></div><div><p className="text-[0.6875rem] text-muted">Demandeur</p><p className="mt-1 text-sm font-semibold text-ink-900">SGSI</p></div><div><p className="text-[0.6875rem] text-muted">Récipiendaires</p><p className="mt-1 text-sm font-semibold text-ink-900">8 personnes</p></div></div><div className="border-t border-line px-5 py-5"><p className="text-sm font-semibold text-ink-900">Résumé de la décision</p><textarea placeholder="Ajouter des indications ou un motif de décision…" className="mt-3 min-h-28 w-full rounded-xl border border-line-strong bg-white p-3 text-sm outline-none focus:border-republic-green-500 focus:ring-4 focus:ring-republic-green-100" /><div className="mt-4 flex flex-wrap gap-2"><Button onClick={() => setModal("approve")}><Icon name="check" className="size-4" />Approuver</Button><Button variant="secondary" onClick={() => setModal("reject")}><Icon name="x" className="size-4" />Rejeter</Button></div>{done ? <p className="mt-4 rounded-xl bg-republic-green-50 p-3 text-xs font-medium text-republic-green-700">{done}</p> : null}</div></WorkspaceCard><Modal open={Boolean(modal)} onClose={() => setModal(null)} title={modal === "approve" ? "Confirmer l'approbation" : "Confirmer le rejet"} description="Cette action est uniquement simulée dans la maquette."><p className="text-sm leading-relaxed text-muted">Vous êtes sur le point d&apos;illustrer une décision pour le dossier DNG-2026-00418. Aucun changement métier réel ne sera effectué.</p><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" size="sm" onClick={() => setModal(null)}>Annuler</Button><Button size="sm" onClick={() => { setDone(modal === "approve" ? "Décision d'approbation simulée." : "Décision de rejet simulée."); setModal(null); }}>{modal === "approve" ? "Confirmer l'approbation" : "Confirmer le rejet"}</Button></div></Modal></>; }

function ServicePage({ page }: { page: DemoPage }) { if (page === "eligibility") return <EligibilityPage />; if (page === "agenda" || page === "ceremonies") return <CeremoniesPage />; if (page === "payments") return <PaymentsPage />; if (page === "delegations") return <DocumentPreviewPage type="Document de délégation" reference="DEL-2026-0026" />; if (page === "attendance") return <AttendancePage />; if (page === "adjustments" || page === "complements" || page === "campaigns") return <GenericListPage page={page} />; return <DossiersPage role="service" go={() => undefined} />; }

function EligibilityPage() { return <><PageIntro eyebrow="Instruction illustrative" title="Validation des distinctions" description="Les seuils et indicateurs ci-dessous sont des repères de démonstration et ne constituent pas un moteur réglementaire." /><WorkspaceCard><CardHeader title="Éligibilité illustrée" action={<ToneBadge label="Repères de maquette" tone="info" />} /><div className="grid gap-4 p-5 sm:grid-cols-3">{[{ type: "bronze" as const, label: "Bronze", threshold: "10 à 19 ans" }, { type: "argent" as const, label: "Argent", threshold: "20 à 29 ans" }, { type: "or" as const, label: "Or", threshold: "30 ans et plus" }].map((item) => <div key={item.label} className="rounded-xl border border-line bg-canvas p-4"><div className="flex items-center gap-3"><span className="w-12"><Medal type={item.type} size="sm" showRibbon={false} /></span><div><p className="text-sm font-semibold text-ink-900">{item.label}</p><p className="mt-1 text-xs text-muted">{item.threshold}</p></div></div></div>)}</div><div className="divide-y divide-line">{ALL_RECIPIENTS.slice(0, 6).map((recipient) => <div key={recipient.id} className="flex flex-wrap items-center gap-4 px-5 py-4"><div className="min-w-48 flex-1"><p className="text-sm font-medium text-ink-900">{recipient.name}</p><p className="mt-1 text-xs text-muted">{recipient.company} · {recipient.seniority} ans déclarés</p></div><span className="text-xs text-muted">Demandé : <strong className="text-ink-800">{recipient.medal}</strong></span><ToneBadge label={recipient.seniority >= (recipient.medal === "Bronze" ? 10 : recipient.medal === "Argent" ? 20 : 30) ? "Seuil atteint" : "À examiner"} tone={recipient.seniority >= (recipient.medal === "Bronze" ? 10 : recipient.medal === "Argent" ? 20 : 30) ? "success" : "warning"} /></div>)}</div></WorkspaceCard></>; }

function AttendancePage() { const [present, setPresent] = useState<Record<string, boolean>>({ REC: true }); return <><PageIntro eyebrow="Organisation" title="Présences" description="Liste illustrative des invités à la cérémonie du 04 avril 2026." /><WorkspaceCard><CardHeader title="Invités et remise des diplômes" /><div className="divide-y divide-line">{ALL_RECIPIENTS.slice(0, 6).map((recipient) => { const isPresent = Boolean(present[recipient.id]); return <div key={recipient.id} className="flex flex-wrap items-center gap-4 px-5 py-4"><div className="flex min-w-48 flex-1 items-center gap-3"><span className="flex size-8 items-center justify-center rounded-full bg-ink-100 text-[0.625rem] font-bold text-ink-700">{recipient.name.slice(0, 2).toUpperCase()}</span><span><span className="block text-sm font-medium text-ink-900">{recipient.name}</span><span className="block text-xs text-muted">Médaille {recipient.medal}</span></span></div><ToneBadge label={isPresent ? "Présence confirmée" : "À confirmer"} tone={isPresent ? "success" : "warning"} /><Button size="sm" variant="ghost" onClick={() => setPresent((current) => ({ ...current, [recipient.id]: !isPresent }))}>{isPresent ? "Marquer absent" : "Confirmer"}</Button></div>; })}</div></WorkspaceCard></>; }

function DocumentPreviewPage({ type, reference }: { type: string; reference: string }) { return <><PageIntro eyebrow="Document imprimable" title={type} description="Aperçu A4 de démonstration. La prévisualisation utilise l'impression du navigateur et aucun sceau officiel n'est fabriqué." action={<Button variant="secondary" size="sm" onClick={() => window.print()}><Icon name="printer" className="size-4" />Imprimer</Button>} /><DocumentPreview type={type} reference={reference} /></>; }

function RegisseurPage({ page }: { page: DemoPage }) { if (page === "stock") return <StockPage />; if (page === "movements") return <MovementsPage />; if (page === "orders" || page === "supplies") return <OrdersPage />; if (page === "deliveries") return <DeliveriesPage />; if (page === "withdrawals") return <WithdrawalsPage />; if (page === "remises") return <DocumentPreviewPage type="Bon de remise des médailles" reference="REM-2026-00418" />; if (page === "campaigns") return <BudgetPage />; return <StockPage />; }

function StockPage() { return <><PageIntro eyebrow="Stock physique" title="Stock des médailles" description="Quantités indicatives, réservations fictives et seuils d'alerte illustratifs." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{STOCK.map((item) => <WorkspaceCard key={item.type} className="p-5"><div className="flex items-start justify-between"><span className={cn("flex size-10 items-center justify-center rounded-xl", item.accent === "gold" ? "bg-gold-100 text-gold-800" : item.accent === "paper" ? "bg-republic-blue-50 text-republic-blue-700" : "bg-republic-green-50 text-republic-green-700")}><Icon name={item.type === "Diplômes" ? "fileText" : "medal"} className="size-5" /></span><ToneBadge label={item.quantity < item.threshold ? "Stock faible" : "Disponible"} tone={item.quantity < item.threshold ? "warning" : "success"} /></div><p className="mt-6 text-sm font-semibold text-ink-900">{item.type}</p><p className="mt-1 text-3xl font-semibold tracking-[-0.05em] text-ink-900">{item.quantity}</p><p className="mt-1 text-xs text-muted">{item.reserved} réservés · seuil démo {item.threshold}</p><div className="mt-5 h-2 rounded-full bg-canvas"><span className="block h-full rounded-full bg-republic-green-500" style={{ width: `${Math.min((item.quantity / (item.quantity + item.reserved)) * 100, 100)}%` }} /></div></WorkspaceCard>)}</div><div className="mt-5"><DataTable columns={[{ key: "type", label: "Type", render: (row) => <span className="font-medium text-ink-900">{row.type}</span> }, { key: "available", label: "Disponible", render: (row) => row.quantity }, { key: "reserved", label: "Réservé", render: (row) => row.reserved }, { key: "last", label: "Dernier mouvement", render: () => "03/03/2026 · Entrée" }, { key: "campaign", label: "Campagne", render: () => CAMPAIGNS[0].split(" — ")[0] }]} rows={STOCK} rowKey={(row) => row.type} /></div></>; }

function MovementsPage() { const rows = STOCK.flatMap((item, index) => [{ id: `${item.type}-in`, date: "03/03/2026", ref: `MV-2026-0${index + 4}`, type: item.type, quantity: index === 3 ? 120 : 36, reason: "Réception fournisseur", author: "Régie des Médailles" }, { id: `${item.type}-out`, date: "28/02/2026", ref: `MV-2026-0${index + 1}`, type: item.type, quantity: item.reserved, reason: "Réservation cérémonie", author: "Régie des Médailles" }]); return <><PageIntro eyebrow="Traçabilité physique" title="Mouvements de stock" description="Entrées et sorties de démonstration liées aux campagnes fictives." /><DataTable columns={[{ key: "date", label: "Date", render: (row) => row.date }, { key: "ref", label: "Référence", render: (row) => <span className="font-semibold text-ink-900">{row.ref}</span> }, { key: "type", label: "Article", render: (row) => row.type }, { key: "quantity", label: "Quantité", render: (row) => <span className="font-semibold text-republic-green-700">+{row.quantity}</span> }, { key: "reason", label: "Motif", render: (row) => row.reason }, { key: "author", label: "Auteur", render: (row) => row.author }]} rows={rows} rowKey={(row) => row.id} /></>; }

function OrdersPage() { const [lines, setLines] = useState([{ type: "Bronze", quantity: 80, price: "18 000 FCFA" }, { type: "Argent", quantity: 40, price: "28 000 FCFA" }]); return <><PageIntro eyebrow="Approvisionnement" title="Bons de commande" description="Prix et quantités fictifs pour illustrer le suivi d'une commande externe." action={<Button onClick={() => setLines((current) => [...current, { type: "Diplômes", quantity: 100, price: "4 500 FCFA" }])}><Icon name="plus" className="size-4" />Ajouter une ligne</Button>} /><WorkspaceCard><CardHeader title="BC-2026-0012" action={<ToneBadge label="En préparation" tone="warning" />} /><div className="overflow-x-auto"><table className="min-w-[600px] w-full text-left text-sm"><thead className="bg-canvas text-[0.625rem] font-bold tracking-[0.12em] text-muted uppercase"><tr><th className="px-5 py-3">Article</th><th className="px-5 py-3">Quantité</th><th className="px-5 py-3">Prix unitaire fictif</th><th /></tr></thead><tbody className="divide-y divide-line">{lines.map((line, index) => <tr key={`${line.type}-${index}`}><td className="px-5 py-4 font-medium text-ink-900">{line.type}</td><td className="px-5 py-4 text-muted">{line.quantity}</td><td className="px-5 py-4 text-muted">{line.price}</td><td className="px-5 py-4 text-right"><button type="button" onClick={() => setLines((current) => current.filter((_, rowIndex) => rowIndex !== index))} className="text-xs font-medium text-red-600">Retirer</button></td></tr>)}</tbody></table></div><div className="flex flex-col items-start justify-between gap-3 border-t border-line p-5 sm:flex-row sm:items-center"><p className="text-xs text-muted">Total indicatif : <strong className="text-ink-900">3 120 000 FCFA</strong> · données fictives</p><Button size="sm" onClick={() => setLines((current) => current)}>Confirmer l&apos;envoi simulé</Button></div></WorkspaceCard></>; }

function DeliveriesPage() { return <><PageIntro eyebrow="Réceptions fournisseur" title="Livraisons" description="Contrôle illustratif des quantités attendues et reçues." /><div className="grid gap-5 md:grid-cols-2">{[{ ref: "LIV-2026-003", date: "03/03/2026", title: "Livraison partielle — BC-2026-0012", detail: "80 Bronze · 40 Argent · 120 diplômes", status: "Partielle", tone: "warning" as const }, { ref: "LIV-2026-002", date: "12/02/2026", title: "Livraison totale — BC-2026-0008", detail: "60 Bronze · 25 Argent · 15 Or", status: "Conforme", tone: "success" as const }].map((item) => <WorkspaceCard key={item.ref} className="p-5"><div className="flex items-center justify-between"><span className="text-[0.6875rem] font-bold tracking-[0.12em] text-muted uppercase">{item.ref}</span><ToneBadge label={item.status} tone={item.tone} /></div><h3 className="mt-4 text-sm font-semibold text-ink-900">{item.title}</h3><p className="mt-2 text-xs text-muted">{item.date} · {item.detail}</p><Button variant="ghost" size="sm" className="mt-5 px-0">Consulter le bordereau <Icon name="arrowRight" className="size-3.5" /></Button></WorkspaceCard>)}</div></>; }

function WithdrawalsPage() { return <><PageIntro eyebrow="Remise physique" title="Retraits sans cérémonie" description="Justificatifs et personnes venues récupérer une distinction, tous fictifs." /><WorkspaceCard><CardHeader title="Demandes de retrait" /><div className="divide-y divide-line">{ALL_RECIPIENTS.slice(0, 5).map((recipient, index) => <div key={recipient.id} className="flex flex-wrap items-center gap-4 px-5 py-4"><div className="flex min-w-48 flex-1 items-center gap-3"><span className="w-10"><Medal type={MEDAL_TYPES[recipient.medal]} size="sm" showRibbon={false} /></span><span><span className="block text-sm font-medium text-ink-900">{recipient.name}</span><span className="block text-xs text-muted">Médaille {recipient.medal} · {recipient.company}</span></span></div><ToneBadge label={index % 2 ? "Justificatif à vérifier" : "Quittance présentée"} tone={index % 2 ? "warning" : "info"} /><Button size="sm" variant="ghost">Consulter</Button></div>)}</div></WorkspaceCard></>; }

function BudgetPage() { return <><PageIntro eyebrow="Pilotage financier" title="Budgets par campagne" description="Montants indicatifs, sans valeur comptable ni engagement réel." /><div className="grid gap-5 md:grid-cols-3">{CAMPAIGNS.map((campaign, index) => <WorkspaceCard key={campaign} className="p-5"><p className="text-xs font-bold tracking-[0.12em] text-muted uppercase">{campaign.split(" — ")[0]}</p><h3 className="mt-3 text-sm font-semibold leading-snug text-ink-900">{campaign.split(" — ")[1]}</h3><div className="mt-6 flex items-end justify-between"><span className="text-2xl font-semibold text-ink-900">{[12.4, 8.7, 5.2][index]} M</span><span className="text-xs text-muted">FCFA alloués</span></div><div className="mt-4 h-2 rounded-full bg-canvas"><span className="block h-full rounded-full bg-republic-green-500" style={{ width: `${[72, 54, 88][index]}%` }} /></div><p className="mt-2 text-xs text-muted">{[72, 54, 88][index]} % consommé · solde indicatif</p></WorkspaceCard>)}</div></>; }

function GenericListPage({ page }: { page: DemoPage }) { const titles: Record<string, [string, string]> = { complements: ["Compléments et justificatifs", "Pièces attendues et réponses simulées"], recours: ["Recours", "Décisions contestées et examens particuliers"], relances: ["Relances", "Demandes de suivi et réponses illustratives"], adjustments: ["Assouplissements", "Situations particulières à examiner"], transmissions: ["Boîte de transmission", "Courriers, dossiers et éléments reçus"], campaigns: ["Statistiques par campagne", "Indicateurs de démonstration par période et campagne"] }; const [title, description] = titles[page] ?? ["Vue détaillée", "Informations de démonstration"]; return <><PageIntro eyebrow="Espace connecté" title={title} description={`${description}. Les informations affichées sont fictives.`} action={<Button><Icon name="plus" className="size-4" />Nouvel élément</Button>} /><div className="grid gap-5 md:grid-cols-3">{["DNG-2026-00418", "DNG-2026-00372", "DNG-2025-01106"].map((reference, index) => <WorkspaceCard key={reference} className="p-5"><div className="flex items-center justify-between"><span className="text-[0.6875rem] font-bold tracking-[0.1em] text-muted uppercase">{page === "transmissions" ? "Courrier" : "Élément"} {index + 1}</span><ToneBadge label={index === 1 ? "En attente" : "En cours"} tone={index === 1 ? "warning" : "info"} /></div><h3 className="mt-4 text-sm font-semibold text-ink-900">{reference}</h3><p className="mt-2 text-xs leading-relaxed text-muted">{page === "complements" ? "Attestation de travail et pièce justificative ciblée." : page === "recours" ? "Examen d'une décision sur l'ancienneté déclarée." : page === "transmissions" ? "Transmission vers le niveau administratif prévu." : "Fiche de démonstration à consulter."}</p><Button variant="ghost" size="sm" className="mt-5 px-0">Consulter <Icon name="arrowRight" className="size-3.5" /></Button></WorkspaceCard>)}</div></>; }

function ProfilePage({ role }: { role: DemoRole }) { return <><PageIntro eyebrow="Compte de démonstration" title="Profil et paramètres" description="Préférences visuelles et informations de session fictives." /><div className="grid gap-5 lg:grid-cols-[0.8fr_1.2fr]"><WorkspaceCard className="p-6 text-center"><span className="mx-auto flex size-20 items-center justify-center rounded-full bg-ink-900 text-xl font-semibold text-white">{ROLE_CONFIGS[role].shortLabel.slice(0, 2).toUpperCase()}</span><h3 className="mt-5 text-lg font-semibold text-ink-900">{ROLE_CONFIGS[role].label}</h3><p className="mt-2 text-sm text-muted">Compte de démonstration</p><ToneBadge label="Session locale" tone="success" /></WorkspaceCard><WorkspaceCard className="p-6"><h3 className="text-sm font-semibold text-ink-900">Préférences</h3><div className="mt-5 space-y-4"><label className="flex items-center justify-between gap-4 rounded-xl border border-line p-4"><span><span className="block text-sm font-medium text-ink-900">Notifications de démonstration</span><span className="mt-1 block text-xs text-muted">Afficher les alertes dans la barre supérieure</span></span><input type="checkbox" defaultChecked className="size-5 accent-republic-green-500" /></label><label className="flex items-center justify-between gap-4 rounded-xl border border-line p-4"><span><span className="block text-sm font-medium text-ink-900">Mode contraste renforcé</span><span className="mt-1 block text-xs text-muted">Préférence visuelle locale</span></span><input type="checkbox" className="size-5 accent-republic-green-500" /></label></div></WorkspaceCard></div></>; }

export default function WorkspacePage({ role, page }: WorkspacePageProps) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [toast, setToast] = useState("");
  const go = (nextPage: DemoPage) => navigateTo(workspacePath(role, nextPage));
  const unread = NOTIFICATIONS.filter((item) => !item.read).length;
  const content = useMemo(() => {
    if (page === "overview") return <Overview role={role} go={go} />;
    if (page === "dossiers" || page === "instruction") return <DossiersPage role={role} go={go} />;
    if (page === "new-dossier") return <NewDossierPage setToast={setToast} />;
    if (page === "recipients") return <RecipientsPage role={role} />;
    if (page === "notifications") return <NotificationsPage />;
    if (page === "activity") return <ActivityPage />;
    if (page === "documents") return <DocumentsPage />;
    if (page === "ceremonies") return <CeremoniesPage />;
    if (page === "payments") return <PaymentsPage />;
    if (page === "decisions") return <NewDecisionPage role={role} />;
    if (role === "service") return <ServicePage page={page} />;
    if (role === "regisseur") return <RegisseurPage page={page} />;
    if (page === "profile") return <ProfilePage role={role} />;
    return <GenericListPage page={page} />;
  }, [page, role]);

  return <div className="min-h-dvh bg-canvas text-ink-900"><div className="flex min-h-dvh"><WorkspaceSidebar role={role} page={page} open={sidebarOpen} onClose={() => setSidebarOpen(false)} /><div className="min-w-0 flex-1"><WorkspaceTopbar role={role} page={page} onMenu={() => setSidebarOpen(true)} unread={unread} onReadAll={() => setToast("Notifications marquées comme lues dans la démonstration.")} /><DemoBanner /><main className="mx-auto max-w-[1500px] px-4 py-7 sm:px-8 lg:px-10">{content}</main><footer className="border-t border-line px-4 py-6 text-center text-[0.6875rem] text-muted sm:px-8">{DEMO_NOTICE} · République Gabonaise — Distinctions Nationales</footer></div></div>{toast ? <div role="status" className="fixed right-4 bottom-4 z-[70] flex max-w-sm items-start gap-3 rounded-xl border border-republic-green-200 bg-white p-4 text-xs text-ink-800 shadow-raised"><Icon name="checkCircle" className="size-4 shrink-0 text-republic-green-600" /><span>{toast}</span><button type="button" onClick={() => setToast("")} className="text-muted"><Icon name="x" className="size-4" /></button></div> : null}</div>;
}